<?php
/** Included inside the existing isolated native inventory fixture. No network. */
if(PHP_SAPI!=='cli'||!defined('CWP_BOOT')||getenv('CWP_TEST_DATABASE')!=='cwp_test')exit(2);
use CajunWebPro\Foundation\Provider\TransportResponse;
use CajunWebPro\Foundation\TwentyIInventory\InventoryRead;
function pi_cloud_client(int $id):array {$saved=$_SESSION;$client=one('SELECT * FROM '.table('studio_clients').' WHERE id=?',[$id]);$_SESSION=['client_id'=>$id,'client_auth'=>$client['auth_version'],'client_login'=>time(),'client_last'=>time()];try{return provider_cloud_client_services($id);}finally{$_SESSION=$saved;}}
pi_aged();$scripted=[new TransportResponse(200,[],json_encode([$cloudItem]))];
pi_ok('Cloud assignment uses a current revision observation',$cloudRefresh(null,7)==='complete');pi_cool();
$approved=provider_inventory_observation($id,InventoryRead::CLOUD_SERVERS_LIST);$rid=$approved['id'];
$network=[$dnsCalls,$transportCalls];
pi_deny('Cloud assignment refuses wrong current password',fn()=>provider_cloud_link($id,1201,1,7,$rid,'wrong'));
pi_deny('Cloud assignment refuses missing client',fn()=>provider_cloud_link($id,1201,999,7,$rid,$password));
pi_deny('Cloud assignment refuses another server',fn()=>provider_cloud_link($id,1202,1,7,$rid,$password));
pi_deny('Cloud assignment refuses stale profile revision',fn()=>provider_cloud_link($id,1201,1,6,$rid,$password));
pi_deny('Cloud assignment refuses stale displayed observation',fn()=>provider_cloud_link($id,1201,1,7,$partial['id'],$password));
pi_deny('Cloud assignment rejects a package observation',fn()=>provider_cloud_link($id,1201,1,7,$packageBefore['id'],$password));
pi_actor(2);pi_deny('Non-owner cannot approve cloud ownership',fn()=>provider_cloud_link($id,1201,1,7,$rid,$password));pi_actor();
pi_ok('Refused cloud assignments have no visibility or event',pi_cloud_client(1)===[]&&pi_count('provider_cloud_link_events')===0);
pi_ok('Cloud link audit failure rolls back assignment and history',pi_audit_failure('cloud_link',fn()=>provider_cloud_link($id,1201,1,7,$rid,$password))&&pi_count('provider_cloud_links')===0&&pi_count('provider_cloud_link_events')===0);
provider_cloud_link($id,1201,1,7,$rid,$password);$cloudLink=provider_cloud_links($id)[0];$clientCloud=pi_cloud_client(1);
pi_ok('Approved cloud link retains exact client context and observation',(int)$cloudLink['client_id']===1&&(int)$cloudLink['profile_revision']===7&&$cloudLink['key_fingerprint']===$approved['key_fingerprint']&&$cloudLink['refresh_id']===$rid);
pi_ok('Client cloud projection retains units without sibling package identifiers',count($clientCloud)===1&&$clientCloud[0]['server']['configuration']['RamMb']===2048&&array_keys($clientCloud[0]['server'])===['id','name','location','product_spec','configuration']&&!str_contains(json_encode($clientCloud),'packageIds')&&!str_contains(json_encode($clientCloud),'key_fingerprint')&&!str_contains(json_encode($clientCloud),'CLOUD_PRIVATE_MARKER'));
pi_ok('Unassigned client receives no cloud server',pi_cloud_client(2)===[]);
pi_deny('Duplicate cloud assignment cannot transfer the server to another client',fn()=>provider_cloud_link($id,1201,2,7,$rid,$password));
pi_ok('Local cloud assignments make no DNS or provider requests',[$dnsCalls,$transportCalls]===$network);
$event=provider_cloud_link_events($id)[0];pi_ok('Cloud approval event retains immutable context',(int)$event['revision']===1&&$event['link_id']===$cloudLink['id']&&$event['refresh_id']===$rid&&$event['key_fingerprint']===$approved['key_fingerprint']);
query('UPDATE '.table('studio_clients').' SET active=0 WHERE id=1');
pi_ok('Inactive client loses cloud projection',pi_cloud_client(1)===[]);
pi_deny('Inactive client cloud assignment cannot be reapproved',fn()=>provider_cloud_relink($cloudLink['id'],1,7,$rid,$password));
query('UPDATE '.table('studio_clients').' SET active=1 WHERE id=1');
// Latest valid observation wins. Do not fall back to older metadata when identity is absent.
$scripted=[new TransportResponse(200,[],json_encode([['id'=>1202,'name'=>'another-client.invalid'],['id'=>false]]))];
pi_ok('Partial observation without linked cloud server is retained',$cloudRefresh(null,7)==='partial');pi_cool();
$hidden=pi_cloud_client(1);pi_ok('Absent server in partial observation exposes no other server',count($hidden)===1&&$hidden[0]['server']===null&&!$hidden[0]['context_changed']&&!str_contains(json_encode($hidden),'another-client'));
$missing=provider_inventory_observation($id,InventoryRead::CLOUD_SERVERS_LIST);
pi_deny('Absent cloud server cannot be reapproved',fn()=>provider_cloud_relink($cloudLink['id'],1,7,$missing['id'],$password));
$scripted=[new TransportResponse(200,[],json_encode([$cloudItem]))];pi_ok('Present server can return under same approved context',$cloudRefresh(null,7)==='complete');pi_cool();
pi_ok('Returning server restores only its approved client projection',pi_cloud_client(1)[0]['server']['id']===1201&&pi_cloud_client(2)===[]);
provider_settings_save($id,7,'Cloud ownership context changed',true,'',$password);
$hidden=pi_cloud_client(1);pi_ok('Profile edit suspends cloud details until explicit reapproval',$hidden[0]['context_changed']&&$hidden[0]['server']===null);
pi_deny('Cloud reapproval requires current observation after settings change',fn()=>provider_cloud_relink($cloudLink['id'],1,8,$rid,$password));
$scripted=[new TransportResponse(200,[],json_encode([$cloudItem]))];pi_ok('Cloud observation refreshes under changed settings',$cloudRefresh(null,8)==='complete');pi_cool();$newRid=provider_inventory_observation($id,InventoryRead::CLOUD_SERVERS_LIST)['id'];
pi_ok('New observation never silently reapproves cloud assignment',pi_cloud_client(1)[0]['server']===null);
$history=all('SELECT * FROM '.table('provider_cloud_link_events').' ORDER BY id');
pi_ok('Cloud reapproval audit failure retains original link and events',pi_audit_failure('cloud_relink',fn()=>provider_cloud_relink($cloudLink['id'],1,8,$newRid,$password))&&(int)provider_cloud_links($id)[0]['revision']===1&&all('SELECT * FROM '.table('provider_cloud_link_events').' ORDER BY id')===$history);
provider_cloud_relink($cloudLink['id'],1,8,$newRid,$password);$newLink=provider_cloud_links($id)[0];
pi_ok('Explicit reapproval advances version and preserves original client',(int)$newLink['revision']===2&&(int)$newLink['client_id']===1&&$newLink['linked_at']===$cloudLink['linked_at']&&$newLink['refresh_id']===$newRid&&pi_cloud_client(1)[0]['server']['id']===1201&&pi_cloud_client(2)===[]);
pi_ok('Reapproval never rewrites original approval event',all('SELECT * FROM '.table('provider_cloud_link_events').' ORDER BY id')[0]===$history[0]);
pi_deny('Stale cloud reapproval form cannot replay',fn()=>provider_cloud_relink($cloudLink['id'],1,8,$newRid,$password));
pi_deny('Stale unlink form cannot remove reapproved assignment',fn()=>provider_cloud_unlink($cloudLink['id'],1,$password));
pi_ok('Cloud unlink audit failure restores assignment and history',pi_audit_failure('cloud_unlink',fn()=>provider_cloud_unlink($cloudLink['id'],2,$password))&&(int)provider_cloud_links($id)[0]['revision']===2&&pi_count('provider_cloud_link_events')===2);
provider_cloud_unlink($cloudLink['id'],2,$password);pi_ok('Unlink removes visibility but preserves all three event contexts',pi_cloud_client(1)===[]&&pi_count('provider_cloud_link_events')===3&&provider_inventory_observation($id,InventoryRead::CLOUD_SERVERS_LIST)['id']===$newRid);
provider_cloud_link($id,1201,2,8,$newRid,$password);$replacement=provider_cloud_links($id)[0];
pi_ok('Explicit new assignment uses a new identity and transfers visibility only after unlink',$replacement['id']!==$cloudLink['id']&&pi_cloud_client(1)===[]&&pi_cloud_client(2)[0]['server']['id']===1201);
pi_deny('Old assignment id cannot unlink a replacement',fn()=>provider_cloud_unlink($cloudLink['id'],2,$password));
provider_settings_state($id,8,'disable',$password);pi_ok('Disabling profile hides assigned cloud metadata',pi_cloud_client(2)[0]['server']===null);
provider_cloud_unlink($replacement['id'],1,$password);pi_ok('Disabled connection still permits safe local unlink',pi_cloud_client(2)===[]);
